// Inline the optional modules (game-data.js, dive-canvas.js) into game.js so the
// single-file build carries them. The build tool only packages game.js + game.json,
// so everything else has to live inside game.js.
//
// Usage:
//   node inline-modules.js           # write the inlined block into game.js
//   node inline-modules.js --check   # fail if game.js is out of date
//
// The block is delimited by the markers below and replaced wholesale, so rerunning
// this is idempotent and hand edits outside the block are never touched.

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const GAME = path.join(ROOT, 'game.js');
const BEGIN = '/* === INLINED-MODULES:BEGIN (generated by inline-modules.js, do not edit) === */';
const END = '/* === INLINED-MODULES:END === */';

const MODULES = [
  { file: 'game-data.js', marker: 'GameData' },
  { file: 'prototype/dive/dive-canvas.js', marker: 'DiveGame' }
];

function buildBlock() {
  const parts = [];
  for (const m of MODULES) {
    const p = path.join(ROOT, m.file);
    if (!fs.existsSync(p)) { console.log('skip (missing): ' + m.file); continue; }
    let src = fs.readFileSync(p, 'utf8');
    // Strip a trailing sourceMappingURL comment; harmless but noisy.
    src = src.replace(/\/\/#\s*sourceMappingURL=.*$/gm, '');
    parts.push(
      '/* --- inlined from ' + m.file + ' --- */\n' +
      '(function () {\n' +
      src + '\n' +
      '})();\n'
    );
    console.log('inline: ' + m.file + '  (' + (src.length / 1024).toFixed(1) + ' KB)');
  }
  return BEGIN + '\n' + parts.join('\n') + END;
}

function main() {
  const checkOnly = process.argv.includes('--check');
  let game = fs.readFileSync(GAME, 'utf8');

  const block = buildBlock();
  const b = game.indexOf(BEGIN);
  const e = game.indexOf(END);

  let out;
  if (b >= 0 && e > b) {
    out = game.slice(0, b) + block + game.slice(e + END.length);
    console.log('replacing existing inlined block');
  } else {
    // Insert right after the "use strict" prologue so the modules are defined
    // before game.js's own IIFE runs and reads window.GameData / window.DiveGame.
    const anchor = game.indexOf("'use strict';");
    if (anchor < 0) { console.log('FAIL: 找不到 use strict 锚点'); process.exit(1); }
    const insertAt = anchor + "'use strict';".length;
    out = game.slice(0, insertAt) + '\n\n  ' + block.replace(/\n/g, '\n  ') + '\n' + game.slice(insertAt);
    console.log('inserted inlined block after use strict');
  }

  if (checkOnly) {
    if (out === game) { console.log('OK: game.js 是最新的'); process.exit(0); }
    console.log('OUT OF DATE: 请运行 node inline-modules.js');
    process.exit(1);
  }
  if (out !== game) {
    fs.writeFileSync(GAME, out, 'utf8');
    console.log('wrote game.js  (' + (out.length / 1024).toFixed(1) + ' KB)');
  } else {
    console.log('no change');
  }
}

main();
